  ["3", "Melquisedeque de Salém", "Confiança e fé; a fé como o ato por meio do qual os homens ganham o favorecimento de Deus", "92:4.7"],
  ["4", "Jesus de Nazaré", "Apresentou Deus como o Pai Universal; a essência do seu ensinamento foi amor e serviço", "92:4.8"],
