  ["Fundamento", "A experiência religiosa pessoal do Jesus da Galiléia", "A experiência religiosa pessoal do apóstolo Paulo", "196:2.1"],
  ["Centro", "Fazer a vontade de Deus e servir à irmandade humana", "A adoração do Jesus glorificado", "196:2.6"],
